(* [comment removed for export] *)
Definition node_havocbrk (cs : acs) (lo hi : Z) : option acs :=
  match xlo (kn cs) (a_brk cs), xhi (kn cs) (a_brk cs) with
  | Some l, Some h =>
      if (fresh_ok cs && Z.leb lo l && Z.leb h hi)%bool then
        let v := nxt cs in let ss := a_ss cs in
        Some (ACS (mk_ss (s_pc ss) (s_regs ss) (KRange (EVar v) lo hi :: s_know ss) (S v))
                  (a_maps cs) (a_totsz cs) (a_ylo cs) (a_eager cs) (a_vis cs) (a_ghost cs) (a_abytes cs) (EVar v) (a_fd cs) (a_tidset cs) (a_hna cs) (a_hlz cs))
      else None
  | _, _ => None
  end.

(* [comment removed for export] *)
Definition node_intro (cs : acs) (lo hi : Z) : option acs :=
  if (fresh_ok cs && Z.leb 0 lo && Z.leb lo hi && Z.ltb hi two64)%bool then
    let v := nxt cs in let ss := a_ss cs in
    Some (with_ss cs (mk_ss (s_pc ss) (s_regs ss) (KRange (EVar v) lo hi :: s_know ss) (S v)))
  else None.

(* [comment removed for export] *)
Fixpoint kfind_litword (k : list kentry) (b : expr) (off : Z) (n : nat) : option Z :=
  match k with
  | [] => None
  | KWord (SA b' off') n' (ELit c) :: r =>
      if (expr_eqb b' b && Z.eqb off' off && Nat.eqb n' n)%bool then Some c else kfind_litword r b off n
  | _ :: r => kfind_litword r b off n
  end.

Definition node_absword (cs : acs) (b : expr) (off : Z) (n : nat) (lo hi : Z) : option acs :=
  if (fresh_ok cs && Nat.leb 1 n && Nat.leb n 8)%bool then
    match kfind_litword (kn cs) b off n with
    | Some c =>
        if (Z.leb lo c && Z.leb c hi && Z.leb 0 lo && Z.ltb hi two64)%bool then
          let v := nxt cs in let ss := a_ss cs in
          let k0 := if expr_eqb b (ELit 0) then kimg_cut (kn cs) off (Z.of_nat n) else kn cs in
          let k' := KWord (SA b off) n (EVar v) :: KRange (EVar v) lo hi :: kn_havoc k0 b off (ELit (Z.of_nat n)) in
          Some (with_ss cs (mk_ss (s_pc ss) (s_regs ss) k' (S v)))
        else None
    | None => None
    end
  else None.

(* [comment removed for export] *)
Definition hop_sub (b n eb en : expr) (h : hop) : hop :=
  let g y := if expr_eqb y n then en else y in
  match h with
  | HCons x y => if expr_eqb x b then HCons eb (g y) else h
  | HSub x y => if expr_eqb x b then HSub eb (g y) else h
  end.
Definition node_habs (cs : acs) (i : nat) (lo hi nlo nhi : Z) : option acs :=
  match nth_error (a_hlz cs) i with
  | Some ev =>
      let b := hop_b ev in let n := hop_n ev in let k := kn cs in
      match xlo k b, xhi k b, xhi k (eadd b n), xlo k n, xhi k n with
      | Some blo, Some bhi, Some ehi, Some nl, Some nh =>
          if (fresh_ok cs && Z.leb lo blo && Z.leb bhi hi && Z.leb ehi hi && Z.leb nlo nl && Z.leb nh nhi && Z.leb 0 lo && Z.ltb hi two64 && Z.leb 0 nlo)%bool then
            let v := nxt cs in let eb := EVar v in let en := EVar (S v) in
            let facts := [KRange eb lo hi; KRange en nlo nhi; KRange (eadd eb en) 0 hi]
                         ++ (if Z.leb 12 (ealign k b) then [KAlign eb 4096] else [])
                         ++ (if Z.leb 12 (ealign k n) then [KAlign en 4096] else []) in
            let ss := a_ss cs in
            Some (ACS (mk_ss (s_pc ss) (s_regs ss) (facts ++ s_know ss) (S (S v)))
                      (a_maps cs) (a_totsz cs) (a_ylo cs) (a_eager cs) (a_vis cs) (a_ghost cs) (a_abytes cs) (a_brk cs) (a_fd cs) (a_tidset cs)
                      (map (hop_sub b n eb en) (a_hna cs)) (map (hop_sub b n eb en) (a_hlz cs)))
          else None
      | _, _, _, _, _ => None
      end
  | None => None
  end.

(* [comment removed for export] *)
Definition SPIN_WORD : Z := 0x6f.
Definition node_spin (cs : acs) : bool :=
  (Z.leb 0 (pc cs) && Z.ltb (pc cs + 4) two64 &&
  match fetch_word segs (Z_to_bv 64 (pc cs)) with
  | Some w => Z.eqb (bv_unsigned w) SPIN_WORD
  | None => false
  end)%bool.

