Definition a_or (A B : av) : option av :=
  reduce (Z.max (alo A) (alo B)) ones64 (Z.land (ak0 A) (ak0 B)) (Z.lor (ak1 A) (ak1 B)).
Lemma a_or_sound : forall A B C x y, gam A x -> gam B y -> a_or A B = Some C -> gam C (zfast ALU_OR x y).
