Definition a_srl (A B : av) : option av :=
  if Z.eqb (alo B) (ahi B) then
    let sh := Z.land (alo B) 63 in
    reduce (Z.shiftr (alo A) sh) (Z.shiftr (ahi A) sh) (Z.shiftr (ak0 A) sh) (Z.shiftr (ak1 A) sh)
  else None.
