Definition a_sltu (A B : av) : option av :=
  if Z.ltb (ahi A) (alo B) then Some (cst 1)
  else if Z.leb (ahi B) (alo A) then Some (cst 0)
  else reduce 0 1 (ones64 - 1) 0.
