Definition fold2 (f : Z -> Z -> Z) (A B : av) : option av :=
  match pt A with
  | Some x => match pt B with
              | Some y => let w := f x y in if in64b w then Some (cst w) else None
              | None => None
              end
  | None => None
  end.
