(* [comment removed for export] *)
Definition kb_try (s : expr) (lo hi : Z) (e : expr) : option Z * option cand :=
  match reduce lo hi 0 0 with
  | Some P => let r := kbc s P e in
              (match fst r with
               | Some A => if Z.eqb (alo A) (ahi A) then Some (alo A) else None
               | None => None
               end, snd r)
  | None => (None, None)
  end.
